$\begin{aligned}\left[\mathrm{Co}\left(\mathrm{NH}_{3}\right)_{6}\right]^{3+}$&$\left[\begin{array}{l}
\text{ inner orbital or }$\\
$\text{ low spin complex }
\end{array}\right]$\\
&$\left(6 \mathrm{NH}_{3}\right. \text{ molecles) }
\end{aligned}<img src="/api/proxy-image?url=https%3A%2F%2Ffirebasestorage.googleapis.com%2Fv0%2Fb%2Fquantrexacademy-app.firebasestorage.app%2Fo%2Fquestions%252Ffigs%252Fpyq%252Fviteee%252Fqbs_yOgwJkvLES5Wa5XZ6BX5GayBQXdJifmZWN9AXmg.original.fullsize.png%3Falt%3Dmedia&clean=1&v=wm2" data-qx-orig-src="https://firebasestorage.googleapis.com/v0/b/quantrexacademy-app.firebasestorage.app/o/questions%2Ffigs%2Fpyq%2Fviteee%2Fqbs_yOgwJkvLES5Wa5XZ6BX5GayBQXdJifmZWN9AXmg.original.fullsize.png?alt=media" data-qx-storage-src="https://firebasestorage.googleapis.com/v0/b/quantrexacademy-app.firebasestorage.app/o/questions%2Ffigs%2Fpyq%2Fviteee%2Fqbs_yOgwJkvLES5Wa5XZ6BX5GayBQXdJifmZWN9AXmg.original.fullsize.png?alt=media">$ \\ 
